import { useEffect, useState, type CSSProperties } from "react";

// model-viewer is a web component; declare the small attribute surface we use.
declare module "react" {
  namespace JSX {
    interface IntrinsicElements {
      "model-viewer": {
        src?: string;
        alt?: string;
        ar?: boolean;
        "ar-modes"?: string;
        "camera-controls"?: boolean;
        "shadow-intensity"?: string;
        style?: CSSProperties;
        className?: string;
      };
    }
  }
}

/**
 * 3D/AR preview of one part's real GLB (public/parts-glb, generated by
 * `npm run parts`). Sits still: no auto-rotate. The AR button appears
 * only where the platform supports it (WebXR / Scene Viewer on Android,
 * Quick Look needs USDZ, which we don't generate yet).
 */
export function PartPreview({ glbFile, partName }: { glbFile: string; partName: string }) {
  // model-viewer is ~600KB of three.js; load it only when a preview shows.
  const [ready, setReady] = useState(false);
  useEffect(() => {
    let live = true;
    import("@google/model-viewer").then(() => { if (live) setReady(true); });
    return () => { live = false; };
  }, []);
  if (!ready) return <p className="fine-print">Loading 3D preview…</p>;
  return (
    <model-viewer
      className="part-preview"
      src={`/parts-glb/${glbFile}`}
      alt={`${partName} in 3D`}
      camera-controls
      ar
      ar-modes="webxr scene-viewer quick-look"
      shadow-intensity="0.7"
      style={{ width: "100%", height: 240, background: "#f7f3ea", borderRadius: 10 }}
    />
  );
}
